import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        long[] dp = new long[n + 2];
        long[] s = new long[n + 2];

        dp[n] = 1;
        s[n] = 1;

        for (int i = n - 1; i >= 1; i--) {
            dp[i] = s[i + 1] % m;
            int limit = n / i;
            for (int j = 2; j <= limit; j++) {
                int h = Math.min(n + 1, (i + 1) * j);
                long value = (s[i * j] - s[h] + m) % m;
                dp[i] = (dp[i] + value) % m;
            }
            s[i] = (s[i + 1] + dp[i]) % m;
        }

        System.out.println(dp[1]);
        sc.close();
    }
}
